#include <bits/stdc++.h>
using namespace std;
int n;
vector<int> head, nxt, to, dist, par, q;
vector<char> seen;

// BFS inside one component; returns (farthest node, its distance).
pair<int, int> farthest(int start) {
    q.clear();
    q.push_back(start);
    dist[start] = 0;
    par[start] = -1;
    pair<int, int> best = {start, 0};
    for (size_t i = 0; i < q.size(); i++) {
        int u = q[i];
        seen[u] = 1;
        if (dist[u] > best.second) best = {u, dist[u]};
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v != par[u]) { par[v] = u; dist[v] = dist[u] + 1; q.push_back(v); }
        }
    }
    return best;
}

int main() {
