    // Keep only edges whose endpoint frequencies differ by at most 1.
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--, b--;
        if (abs(f[a] - f[b]) <= 1) {
