import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static int[] head, nxt, to, dist, par, q;
    static boolean[] seen;

    // BFS inside one component; returns {farthest node, its distance}.
    static int[] farthest(int start) {
        int qh = 0, qt = 0;
        q[qt++] = start;
        dist[start] = 0;
        par[start] = -1;
        int bestNode = start, bestDist = 0;
        while (qh < qt) {
            int u = q[qh++];
            seen[u] = true;
            if (dist[u] > bestDist) { bestNode = u; bestDist = dist[u]; }
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (v != par[u]) { par[v] = u; dist[v] = dist[u] + 1; q[qt++] = v; }
            }
        }
        return new int[]{bestNode, bestDist};
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] f = new int[n];
        for (int i = 0; i < n; i++) f[i] = nextInt();
        head = new int[n];
        java.util.Arrays.fill(head, -1);
        nxt = new int[2 * n];
        to = new int[2 * n];
        int edges = 0;
        // Keep only edges whose endpoint frequencies differ by at most 1.
        for (int i = 0; i < n - 1; i++) {
            int a = nextInt() - 1, b = nextInt() - 1;
            if (Math.abs(f[a] - f[b]) <= 1) {
                to[edges] = b; nxt[edges] = head[a]; head[a] = edges++;
                to[edges] = a; nxt[edges] = head[b]; head[b] = edges++;
            }
        }
        dist = new int[n];
        par = new int[n];
        q = new int[n];
        seen = new boolean[n];
        int answer = 0;
        for (int i = 0; i < n; i++) {
            if (!seen[i]) {
                int end = farthest(i)[0];
                answer = Math.max(answer, farthest(end)[1]);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

var head, nxt, to, dist, par, q []int
var seen []bool

// BFS inside one component; returns the farthest node and its distance.
func farthest(start int) (int, int) {
	q = q[:0]
	q = append(q, start)
	dist[start] = 0
	par[start] = -1
	bestNode, bestDist := start, 0
	for i := 0; i < len(q); i++ {
		u := q[i]
		seen[u] = true
		if dist[u] > bestDist {
			bestNode, bestDist = u, dist[u]
		}
		for e := head[u]; e != -1; e = nxt[e] {
			v := to[e]
			if v != par[u] {
				par[v] = u
				dist[v] = dist[u] + 1
				q = append(q, v)
			}
		}
	}
	return bestNode, bestDist
}

func main() {
	n := readInt()
	f := make([]int, n)
	for i := range f {
		f[i] = readInt()
	}
	head = make([]int, n)
	for i := range head {
		head[i] = -1
	}
	// Keep only edges whose endpoint frequencies differ by at most 1.
	for i := 0; i < n-1; i++ {
		a, b := readInt()-1, readInt()-1
		d := f[a] - f[b]
		if d >= -1 && d <= 1 {
			to = append(to, b)
			nxt = append(nxt, head[a])
			head[a] = len(to) - 1
			to = append(to, a)
			nxt = append(nxt, head[b])
			head[b] = len(to) - 1
		}
	}
	dist = make([]int, n)
	par = make([]int, n)
	q = make([]int, 0, n)
	seen = make([]bool, n)
	answer := 0
	for i := 0; i < n; i++ {
		if !seen[i] {
			end, _ := farthest(i)
			if _, d := farthest(end); d > answer {
				answer = d
			}
		}
	}
	fmt.Println(answer)
}
